-- Strictly read-only, for Staging/Production baseline; no rows with personal data are exported.
WITH p AS (SELECT p.tenant_id,p.site_id,p.subscriber_id,p.invoice_id,p.amount,p.status,i.id matched_invoice,i.tenant_id invoice_tenant,i.site_id invoice_site,i.subscriber_id invoice_subscriber FROM public.payments p LEFT JOIN public.invoices i ON i.id=p.invoice_id)
SELECT jsonb_build_object('payments',(SELECT jsonb_build_object('rows',count(*),'completed',count(*) FILTER (WHERE status='completed'),'totalAmount',coalesce(sum(amount),0),'completedAmount',coalesce(sum(amount) FILTER (WHERE status='completed'),0),'completedUnlinkedCount',count(*) FILTER (WHERE status='completed' AND invoice_id IS NULL),'orphanInvoices',count(*) FILTER (WHERE invoice_id IS NOT NULL AND matched_invoice IS NULL),'crossScopeInvoices',count(*) FILTER (WHERE matched_invoice IS NOT NULL AND (tenant_id<>invoice_tenant OR site_id<>invoice_site OR subscriber_id<>invoice_subscriber)),'nonpositive',count(*) FILTER (WHERE amount<=0),'excessDecimalPrecision',count(*) FILTER (WHERE amount<>round(amount,2))) FROM p),'columns',(SELECT coalesce(jsonb_agg(column_name ORDER BY column_name),'[]'::jsonb) FROM information_schema.columns WHERE table_schema='public' AND table_name='payments' AND column_name IN ('amount','payment_purpose','invoice_applied_amount','subscriber_credit_amount')),'liabilityLedgerExists',to_regclass('public.subscriber_balance_ledger') IS NOT NULL,'constraints',(SELECT coalesce(jsonb_agg(conname ORDER BY conname),'[]'::jsonb) FROM pg_constraint WHERE conrelid='public.payments'::regclass AND conname IN ('payments_payment_purpose_check','payments_invoice_credit_split_check')),'migrations',(SELECT coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name,'sqlAvailable', statements IS NOT NULL AND cardinality(statements)>0) ORDER BY version),'[]'::jsonb) FROM supabase_migrations.schema_migrations WHERE version IN ('20261103131052','20261103131104','20261103131125','20261103145232') OR name IN ('powerhub_subscriber_credit_ledger','powerhub_subscriber_liability_and_cash_allocation','powerhub_statement_operating_collection_summary','powerhub_legacy_unlinked_payments_to_subscriber_credit'))) AS audit;
